//! D: `azul.d` (module `azul`, generated by `doc/src/codegen/v2/lang_d`).
//!
//! Spellings: the native API - lowerCamel members with the D generator's
//! `camel` rule (`LayoutDisplay.flex`, `OsCondition.macOS`), a trailing `_`
//! for D keywords and reserved members (`LayoutWidth.auto_()`,
//! `CssProperty.float_(..)`), enum variants as static functions
//! (`LayoutWidth.px(..)`, `LayoutWidthValue.exact(..)`, the variant
//! overload `CssProperty.whiteSpace(StyleWhiteSpaceValue)` next to the
//! api.json `CssProperty.width(LayoutWidth)`), structs through positional
//! `opCall` (`ColorU(255, 0, 0, 255)`), api `create` as the constructor
//! (`FloatValue(1.0f)`), native arrays for Vecs and native strings.

use alloc::{
    format,
    string::{String, ToString},
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{EnumShape, Item, Module, Prim},
    lang::{
        escape_quoted, is_droppable_vec, item_comments, item_doc, swift::swift_camel,
        unicode_u4, ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The D printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct D;

const KEYWORDS: &[&str] = &[
    "abstract", "alias", "align", "asm", "assert", "auto", "bool", "break", "byte", "case",
    "cast", "catch", "cdouble", "cent", "cfloat", "char", "class", "const", "continue", "creal",
    "dchar", "debug", "default", "delegate", "deprecated", "do", "double", "else", "enum",
    "export", "extern", "false", "final", "finally", "float", "for", "foreach",
    "foreach_reverse", "function", "goto", "idouble", "if", "ifloat", "immutable", "import",
    "in", "inout", "int", "interface", "invariant", "ireal", "is", "lazy", "long", "macro",
    "mixin", "module", "new", "nothrow", "null", "out", "override", "package", "pragma",
    "private", "protected", "public", "pure", "real", "ref", "return", "scope", "shared",
    "short", "static", "struct", "super", "switch", "synchronized", "template", "this", "throw",
    "true", "try", "typeid", "typeof", "ubyte", "ucent", "uint", "ulong", "union", "unittest",
    "ushort", "version", "void", "wchar", "while", "with",
];

/// Members every D aggregate already has (the wrappers suffix them too).
const RESERVED_MEMBERS: &[&str] = &[
    "init", "tag", "dup", "sizeof", "alignof", "mangleof", "stringof", "offsetof",
];

fn member(name: &str) -> String {
    let n = swift_camel(name);
    if KEYWORDS.contains(&n.as_str()) || RESERVED_MEMBERS.contains(&n.as_str()) {
        format!("{n}_")
    } else {
        n
    }
}

impl ExprSyntax for D {
    fn int(&self, value: i128, ty: Prim) -> String {
        match ty {
            Prim::Isize => format!("cast(ptrdiff_t) {value}"),
            Prim::Usize => format!("cast(size_t) {value}"),
            Prim::U32 => format!("{value}u"),
            Prim::U64 => format!("{value}UL"),
            Prim::I64 => format!("{value}L"),
            _ => value.to_string(),
        }
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let (t, suffix) = if ty == Prim::F64 { ("double", "") } else { ("float", "f") };
        match text {
            "nan" => format!("{t}.nan"),
            "inf" => format!("{t}.infinity"),
            "-inf" => format!("-{t}.infinity"),
            _ => format!("{text}{suffix}"),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("\"{}\"", escape_quoted(s, &[], &unicode_u4)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        if method == "create" {
            Doc::call(class.to_string(), args, broken)
        } else {
            Doc::call(format!("{class}.{}", member(method)), args, broken)
        }
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("{ty}.{}", member(variant))),
            EnumShape::Tagged | EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                Doc::call(format!("{ty}.{}", member(variant)), args, broken)
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        Doc::call(ty.to_string(), fields.into_iter().map(|(_, v)| v).collect(), broken)
    }

    fn vec(&self, _ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        Doc::list("[", items, ", ", "]", false, broken, true)
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("assert(0, {:?})", format!("not expressible: {what}")))
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&D, item) {
        out.push_str(&format!("// {line}\n"));
    }
    let name = item.name.lower_camel();
    let ty = if is_droppable_vec(&item.ty) {
        "CssPropertyWithConditions[]".to_string()
    } else {
        item.ty.clone()
    };
    match item_doc(&D, item) {
        Ok(doc) => out.push_str(&format!(
            "{ty} {name}()\n{{\n    return {};\n}}\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!("// not expressible with the D bindings: {reason}\n")),
    }
    out
}

impl CodegenBackend for D {
    fn lang(&self) -> &'static str {
        "d"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["dlang"]
    }

    fn display_name(&self) -> &'static str {
        "D"
    }

    fn extension(&self) -> &'static str {
        "d"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out = String::from(
            "// Generated by azul-css codegen (D). Do not edit by hand.\nmodule styles;\n\nimport \
             azul;\n",
        );
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::from(
            "// Copy target/codegen/azul.d and libazul next to this file, then:\n//   ldc2 main.d \
             styles.d azul.d -L-L. -L-lazul && ./main\nimport std.stdio;\nimport \
             styles;\n\nvoid main()\n{\n",
        );
        for item in &m.items {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "    auto {name}Value = {name}();\n    writeln(\"{name}: \", {name}Value.length, \" \
                 properties\");\n"
            ));
        }
        main.push_str("}\n");
        let mut files = Vec::new();
        files.push(GeneratedFile {
            path: "styles.d".to_string(),
            contents: self.emit_module(m),
        });
        files.push(GeneratedFile {
            path: "main.d".to_string(),
            contents: main,
        });
        files
    }
}
